def _load_config_menu():
    global FIXED_DELIVERY_CHARGE
    candidates = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), CONFIG_FILE),
        CONFIG_FILE,
    ]
    for path in candidates:
        try:
            if os.path.exists(path):
                with open(path, encoding="utf-8") as f:
                    cfg = json.load(f)
                items = cfg.get("items") or cfg.get("menu") or []
                loaded = {}
                for entry in items:
                    name = str(entry.get("name", "")).strip().lower()
                    price = int(entry.get("price", entry.get("price_pkr", 0)) or 0)
                    if name and price > 0:
                        loaded[name] = price
                if loaded:
                    MENU.clear()
                    MENU.update(loaded)
                if os.getenv("FIXED_DELIVERY_CHARGE") is None and cfg.get("delivery_charge") is not None:
                    FIXED_DELIVERY_CHARGE = int(cfg["delivery_charge"])
                elif os.getenv("FIXED_DELIVERY_CHARGE") is None and cfg.get("delivery_charge_pkr"):
                    FIXED_DELIVERY_CHARGE = int(cfg["delivery_charge_pkr"])
                print(f"Loaded menu from {path}: {len(MENU)} items")
                return
        except Exception as e:
            print(f"Could not load config JSON ({path}): {e}")
    print(f"No {CONFIG_FILE} found, using built-in menu")

def _save_config_menu():
    """Write the in-memory MENU + delivery charge back to the config JSON,
    keeping every other field in the file. Called after owner menu edits,
    so a price change survives a server restart."""
    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), CONFIG_FILE)
        data = {}
        if os.path.exists(path):
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        data["items"] = [{"name": name, "price": price} for name, price in MENU.items()]
        data["delivery_charge"] = FIXED_DELIVERY_CHARGE
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        return True
    except Exception as e:
        print(f"Error saving config JSON: {e}")
        return False

_load_config_menu()

def menu_text() -> str:
    lines = [f"🍽️ *{BUSINESS_NAME.upper()} - MENU*\n"]
    for name, price in MENU.items():
        lines.append(f"• {name.title()} - {CUR} {price}")
    lines.append(f"\n🚚 Delivery: {CUR} {FIXED_DELIVERY_CHARGE}")
    lines.append(f"\n{MSG['menu_footer']}")
    return "\n".join(lines)

def format_whatsapp_number(number: str) -> str:
    number = (number or "").strip()
    if not number:
        return ""
    return number if number.startswith("whatsapp:") else f"whatsapp:{number}"

security = HTTPBasic()

def require_admin(credentials: HTTPBasicCredentials = Depends(security)):
    if not ADMIN_PASSWORD:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="Admin password is not set. Set ADMIN_PASSWORD in .env first.",
        )
    user_ok = secrets.compare_digest(credentials.username, ADMIN_USERNAME)
    pass_ok = secrets.compare_digest(credentials.password, ADMIN_PASSWORD)
    if not (user_ok and pass_ok):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect admin login",
            headers={"WWW-Authenticate": "Basic"},
        )
    return credentials.username

def secret_status(value: str) -> str:
    return "✅ Set" if value else "❌ Not set"

SHEET_HEADERS = [
    "Order ID", "Date", "Name", "Phone", "Address",
    "Items", "Grand Total", "Status", "Rider Name", "Rider Phone",
]

def get_google_sheet():
    try:
        scopes = ["https://www.googleapis.com/auth/spreadsheets"]
        creds = None
        # Railway has no way to upload a credentials.json file, so the whole
        # service-account JSON can be pasted into GOOGLE_CREDENTIALS_JSON
        # (Railway Variables). It wins over the file. Invalid JSON is logged
        # and the Sheet is skipped — the bot never crashes over it.
        env_creds = (os.getenv("GOOGLE_CREDENTIALS_JSON") or "").strip()
        if env_creds:
            creds = Credentials.from_service_account_info(json.loads(env_creds), scopes=scopes)
        elif os.path.exists("credentials.json"):
            creds = Credentials.from_service_account_file("credentials.json", scopes=scopes)
        if creds is not None:
            client = gspread.authorize(creds)
            sheet = client.open(BUSINESS_NAME).sheet1
            try:
                first_row = sheet.row_values(1)
                if first_row != SHEET_HEADERS:
                    if not first_row:
                        sheet.append_row(SHEET_HEADERS)
            except Exception:
                pass
            return sheet
    except Exception as e:
        print(f"Google Sheet Connection Error: {e}")
    return None

