def _canonical_digits(phone):
    digits = re.sub(r"\D", "", phone or "")
    if digits.startswith("0") and len(digits) == 11:
        digits = "92" + digits[1:]
    return digits

def _normalise_phone_for_send(phone):
    digits = _canonical_digits(phone)
    return ("+" + digits) if len(digits) >= 10 else ""

def _known_customer_phones():
    """All customer numbers the bot knows: orders in this run + the
    Google Sheet's Phone column. Returns canonical digit strings."""
    phones = set()
    for order in confirmed_orders.values():
        p = _canonical_digits(order.get("Phone", ""))
        if p:
            phones.add(p)
    try:
        sheet = get_google_sheet()
        if sheet:
            for row in sheet.get_all_records():
                p = _canonical_digits(row.get("Phone", ""))
                if p:
                    phones.add(p)
    except Exception as e:
        print(f"Error reading customer phones from sheet: {e}")
    return phones

def _broadcast_to_customers(body, media_url=None):
    """Send a message/banner to every known customer, one by one,
    skipping only the owner/kitchen numbers. Returns (sent, failed)."""
    sent, failed = 0, 0
    skip = {_canonical_digits(OWNER_WHATSAPP or ""), _canonical_digits(KITCHEN_WHATSAPP or "")}
    for phone in sorted(_known_customer_phones()):
        if phone in skip:
            continue
        if send_whatsapp_message(_normalise_phone_for_send(phone), body, media_url=media_url):
            sent += 1
        else:
            failed += 1
        time.sleep(0.5)
    return sent, failed

def _offer_call_url(offer_text):
    # The calling agent serves /offer-call when it has its own domain;
    # otherwise this bot serves the same TwiML from SERVER_URL.
    base = (CALLING_AGENT_URL or SERVER_URL or "").rstrip("/")
    if not base:
        return ""
    return f"{base}/offer-call?{urlencode({'text': offer_text})}"

def _place_offer_call(phone, offer_text):
    """Place one outbound offer call to a customer. Returns True on
    success (or when Twilio is not configured, the call is logged)."""
    url = _offer_call_url(offer_text)
    if not url:
        print("No SERVER_URL/CALLING_AGENT_URL, offer call not placed")
        return False
    if not TWILIO_VOICE_NUMBER:
        print("No TWILIO_VOICE_NUMBER, offer call not placed")
        return False
    if not twilio_client:
        print(f"Twilio not configured, would call {phone}: {url}")
        return True
    try:
        twilio_client.calls.create(to=phone, from_=TWILIO_VOICE_NUMBER, url=url)
        return True
    except Exception as e:
        print(f"Offer Call Error ({phone}): {e}")
        return False

@app.api_route("/offer-call", methods=["GET", "POST"])
async def offer_call(text: str = ""):
    """TwiML the calling agent speaks when an outbound offer call connects.
    Same wording lives in the calling agent file — it serves this endpoint
    when CALLING_AGENT_URL is set; this copy is the fallback."""
    from twilio.twiml.voice_response import VoiceResponse
    vr = VoiceResponse()
    vr.say(f"Assalam o Alaikum! {BUSINESS_NAME} ki taraf se ek khaas offer hai. {text} Order karne ke liye WhatsApp par apna order likh kar bhejein, ya is number par wapas call karein. Shukriya! Khuda Hafiz.")
    vr.hangup()
    return Response(content=str(vr), media_type="application/xml")

